using System.Globalization;
using System.Text;

namespace BatchRenameStudio.Core;

/// <summary>
/// Pure helpers implementing the literal name semantics of the plan contract
/// (split, reassembly, validity). No IO, no culture dependence.
/// </summary>
public static class NameRules
{
    public const int MaxNameLength = 255;

    private static readonly char[] ForbiddenChars = { '<', '>', ':', '"', '/', '\\', '|', '?', '*' };

    private static readonly HashSet<string> ReservedDeviceNames =
        new(StringComparer.OrdinalIgnoreCase)
        {
            "CON", "PRN", "AUX", "NUL",
            "COM1", "COM2", "COM3", "COM4", "COM5", "COM6", "COM7", "COM8", "COM9",
            "LPT1", "LPT2", "LPT3", "LPT4", "LPT5", "LPT6", "LPT7", "LPT8", "LPT9",
        };

    /// <summary>
    /// Contract rule 2: dot = index of the LAST '.'; if dot &gt; 0 the name splits into
    /// base = [0,dot) and ext = (dot,end] (no dot in ext), otherwise ext is empty.
    /// </summary>
    public static (string Base, string Ext) Split(string name)
    {
        int dot = name.LastIndexOf('.');
        if (dot > 0) return (name[..dot], name[(dot + 1)..]);
        return (name, string.Empty);
    }

    /// <summary>Contract rule 12: base + "." + ext, or just base when ext is empty.</summary>
    public static string Join(string baseName, string ext) =>
        ext.Length == 0 ? baseName : baseName + "." + ext;

    /// <summary>
    /// Contract rule 13, first bullet. Returns null when the name is valid, otherwise a short reason.
    /// </summary>
    public static string? GetInvalidReason(string proposed)
    {
        if (proposed.Length == 0) return "empty name";
        if (proposed.Length > MaxNameLength) return $"longer than {MaxNameLength} characters";

        foreach (char c in proposed)
        {
            if (c < ' ') return $"control character U+{(int)c:X4}";
            if (Array.IndexOf(ForbiddenChars, c) >= 0) return $"forbidden character '{c}'";
        }

        var (baseName, _) = Split(proposed);
        if (ReservedDeviceNames.Contains(baseName)) return $"reserved device name '{baseName}'";

        return null;
    }

    public static bool IsValid(string proposed) => GetInvalidReason(proposed) is null;

    /// <summary>
    /// Contract rule 10, "title": for each maximal run of Unicode letters, uppercase the first
    /// character and lowercase the rest. Non-letters are untouched.
    /// </summary>
    public static string ToTitle(string value)
    {
        if (value.Length == 0) return value;

        var sb = new StringBuilder(value.Length);
        bool inRun = false;
        foreach (char c in value)
        {
            if (char.IsLetter(c))
            {
                sb.Append(inRun ? char.ToLowerInvariant(c) : char.ToUpperInvariant(c));
                inRun = true;
            }
            else
            {
                sb.Append(c);
                inRun = false;
            }
        }
        return sb.ToString();
    }

    public static string ToUpper(string value) => value.ToUpperInvariant();

    public static string ToLower(string value) => value.ToLowerInvariant();

    /// <summary>Formats a counter value with the given zero-pad width, culture invariantly.</summary>
    public static string FormatCounter(long value, int padWidth) =>
        value.ToString(new string('0', Math.Max(1, padWidth)), CultureInfo.InvariantCulture);
}

