using System.Text.RegularExpressions;

namespace BatchRenameStudio.Core;

/// <summary>Thrown when a rule set cannot be turned into a runnable plan (e.g. a bad regex).</summary>
public sealed class RuleException : Exception
{
    public RuleException(string message) : base(message) { }
}

/// <summary>
/// Turns a folder listing plus a rule set into a <see cref="RenamePlan"/>.
/// This type is the single source of truth for the rename semantics: the headless
/// <c>--plan</c> mode and the GUI preview both call <see cref="BuildPlan"/>.
/// </summary>
public static class RenameEngine
{
    private static readonly Regex CounterToken = new(@"\{n:(0+)\}", RegexOptions.CultureInvariant);

    public static RenamePlan BuildPlan(IReadOnlyList<FileEntry> files, RuleSet rules)
    {
        var steps = Prepare(rules);
        var ordered = Sort(files, rules.Sort);

        var proposals = new string[ordered.Count];
        for (int i = 0; i < ordered.Count; i++)
        {
            proposals[i] = Apply(ordered[i].Name, rules.ApplyTo, steps, i);
        }

        return Classify(ordered, proposals);
    }

    /// <summary>Contract rule 5 + rule 15: deterministic processing order.</summary>
    public static List<FileEntry> Sort(IReadOnlyList<FileEntry> files, SortMode mode) => mode switch
    {
        // Ordinal (codepoint) ascending, case sensitive.
        SortMode.Name => files.OrderBy(f => f.Name, StringComparer.Ordinal).ToList(),
        // Timestamp ascending; the ordinal name is a tie-break so equal timestamps stay deterministic.
        SortMode.Created => files.OrderBy(f => f.CreatedUtc).ThenBy(f => f.Name, StringComparer.Ordinal).ToList(),
        SortMode.Modified => files.OrderBy(f => f.ModifiedUtc).ThenBy(f => f.Name, StringComparer.Ordinal).ToList(),
        _ => files.OrderBy(f => f.Name, StringComparer.Ordinal).ToList(),
    };

    /// <summary>
    /// Runs every step over one file name. <paramref name="ordinal"/> is the 0-based position in
    /// processing order and drives the sequence counter (which advances for every file).
    /// </summary>
    public static string Apply(string originalName, ApplyTo applyTo, IReadOnlyList<PreparedStep> steps, int ordinal)
    {
        if (applyTo == ApplyTo.NameAndExtension)
        {
            string whole = originalName;
            foreach (var step in steps)
            {
                whole = step.Def.Op == StepOp.Extension
                    // Rule 11 + 12: an extension step always works on the trailing extension,
                    // even when the target string is the whole name.
                    ? ApplyExtensionToWholeName(whole, step)
                    : ApplyToTarget(whole, step, ordinal);
            }
            return whole;
        }

        var (baseName, ext) = NameRules.Split(originalName);
        foreach (var step in steps)
        {
            if (step.Def.Op == StepOp.Extension) ext = ApplyExtension(ext, step);
            else baseName = ApplyToTarget(baseName, step, ordinal);
        }
        return NameRules.Join(baseName, ext);
    }

    private static string ApplyExtensionToWholeName(string whole, PreparedStep step)
    {
        var (b, e) = NameRules.Split(whole);
        return NameRules.Join(b, ApplyExtension(e, step));
    }

    private static string ApplyExtension(string ext, PreparedStep step) => step.Def.ExtensionMode switch
    {
        ExtensionMode.Lower => NameRules.ToLower(ext),
        ExtensionMode.Upper => NameRules.ToUpper(ext),
        ExtensionMode.Set => step.Def.Value,
        _ => ext,
    };

    private static string ApplyToTarget(string target, PreparedStep step, int ordinal)
    {
        var d = step.Def;
        switch (d.Op)
        {
            case StepOp.Replace:
                if (d.Find.Length == 0) return target;           // nothing to look for: no-op
                return step.Rx is not null
                    ? step.Rx.Replace(target, d.ReplaceWith)
                    : target.Replace(d.Find, d.ReplaceWith,
                        d.IgnoreCase ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal);

            case StepOp.Insert:
                switch (d.Position)
                {
                    case InsertPosition.Prefix: return d.Text + target;
                    case InsertPosition.Suffix: return target + d.Text;
                    default:
                        int at = Math.Clamp(d.Index, 0, target.Length);
                        return target.Insert(at, d.Text);
                }

            case StepOp.Remove:
            {
                int from = Math.Clamp(d.From, 0, target.Length);
                int count = Math.Clamp(d.Count, 0, target.Length - from);
                return count == 0 ? target : target.Remove(from, count);
            }

            case StepOp.Sequence:
            {
                long value = d.Start + (long)ordinal * d.Step;
                string rendered = RenderSequence(d.Pattern, value);
                return d.SeqPosition == SequencePosition.Suffix ? target + rendered : rendered + target;
            }

            case StepOp.Case:
                return d.CaseMode switch
                {
                    CaseMode.Upper => NameRules.ToUpper(target),
                    CaseMode.Lower => NameRules.ToLower(target),
                    _ => NameRules.ToTitle(target),
                };

            default:
                return target;
        }
    }

    /// <summary>Expands the <c>{n:000}</c> token(s) of a sequence pattern; other text is literal.</summary>
    public static string RenderSequence(string pattern, long value) =>
        CounterToken.Replace(pattern, m => NameRules.FormatCounter(value, m.Groups[1].Value.Length));

    /// <summary>Contract rule 13: status precedence invalid &gt; collision &gt; unchanged &gt; ok.</summary>
    private static RenamePlan Classify(IReadOnlyList<FileEntry> ordered, IReadOnlyList<string> proposals)
    {
        var existing = new HashSet<string>(ordered.Select(f => f.Name), StringComparer.OrdinalIgnoreCase);

        var proposedCounts = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        foreach (var p in proposals)
        {
            proposedCounts.TryGetValue(p, out int n);
            proposedCounts[p] = n + 1;
        }

        var plan = new RenamePlan();
        for (int i = 0; i < ordered.Count; i++)
        {
            string original = ordered[i].Name;
            string proposed = proposals[i];

            string status;
            string reason;

            string? invalid = NameRules.GetInvalidReason(proposed);
            if (invalid is not null)
            {
                status = PlanStatus.Invalid;
                reason = invalid;
            }
            else if (proposedCounts[proposed] > 1)
            {
                status = PlanStatus.Collision;
                reason = "another item proposes the same name";
            }
            else if (existing.Contains(proposed) && !string.Equals(proposed, original, StringComparison.OrdinalIgnoreCase))
            {
                status = PlanStatus.Collision;
                reason = "a different existing file already uses this name";
            }
            else if (string.Equals(proposed, original, StringComparison.Ordinal))
            {
                status = PlanStatus.Unchanged;
                reason = "";
            }
            else
            {
                status = PlanStatus.Ok;
                reason = "";
            }

            plan.Items.Add(new PlanItem(original, proposed, status, reason));
        }

        plan.Summary.Total = plan.Items.Count;
        plan.Summary.Ok = plan.Items.Count(i => i.Status == PlanStatus.Ok);
        plan.Summary.Collision = plan.Items.Count(i => i.Status == PlanStatus.Collision);
        plan.Summary.Unchanged = plan.Items.Count(i => i.Status == PlanStatus.Unchanged);
        plan.Summary.Invalid = plan.Items.Count(i => i.Status == PlanStatus.Invalid);
        return plan;
    }

    /// <summary>A step with its per-run state (a compiled regex) resolved once instead of per file.</summary>
    public sealed class PreparedStep
    {
        public PreparedStep(RuleStep def, Regex? rx)
        {
            Def = def;
            Rx = rx;
        }

        public RuleStep Def { get; }
        public Regex? Rx { get; }
    }

    public static List<PreparedStep> Prepare(RuleSet rules)
    {
        var list = new List<PreparedStep>(rules.Steps.Count);
        for (int i = 0; i < rules.Steps.Count; i++)
        {
            var s = rules.Steps[i];
            if (!s.Enabled) continue;

            Regex? rx = null;
            if (s.Op == StepOp.Replace && s.Regex && s.Find.Length > 0)
            {
                var options = RegexOptions.CultureInvariant;
                if (s.IgnoreCase) options |= RegexOptions.IgnoreCase;
                try
                {
                    rx = new Regex(s.Find, options);
                }
                catch (ArgumentException ex)
                {
                    throw new RuleException($"step {i + 1} (replace): invalid regex \"{s.Find}\": {ex.Message}");
                }
            }
            list.Add(new PreparedStep(s, rx));
        }
        return list;
    }
}

