using System.Text;
using System.Text.Encodings.Web;
using System.Text.Json;

namespace BatchRenameStudio.Core;

/// <summary>Thrown when a rules.json file does not match the documented contract.</summary>
public sealed class RulesFormatException : Exception
{
    public RulesFormatException(string message) : base(message) { }
}

/// <summary>Reader/writer for the fixed <c>rules.json</c> contract.</summary>
public static class RulesJson
{
    public static RuleSet Load(string path)
    {
        string text;
        try
        {
            text = File.ReadAllText(path);
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            throw new RulesFormatException($"cannot read rules file \"{path}\": {ex.Message}");
        }
        return Parse(text);
    }

    public static RuleSet Parse(string json)
    {
        JsonDocument doc;
        try
        {
            doc = JsonDocument.Parse(json, new JsonDocumentOptions
            {
                CommentHandling = JsonCommentHandling.Skip,
                AllowTrailingCommas = true,
            });
        }
        catch (JsonException ex)
        {
            throw new RulesFormatException($"rules file is not valid JSON: {ex.Message}");
        }

        using (doc)
        {
            var root = doc.RootElement;
            if (root.ValueKind != JsonValueKind.Object)
                throw new RulesFormatException("rules file root must be a JSON object");

            var rules = new RuleSet
            {
                ApplyTo = ReadEnum(root, "applyTo", ApplyTo.Name, new()
                {
                    ["name"] = ApplyTo.Name,
                    ["nameandextension"] = ApplyTo.NameAndExtension,
                }),
                Sort = ReadEnum(root, "sort", SortMode.Name, new()
                {
                    ["name"] = SortMode.Name,
                    ["created"] = SortMode.Created,
                    ["modified"] = SortMode.Modified,
                }),
            };

            if (root.TryGetProperty("steps", out var steps))
            {
                if (steps.ValueKind != JsonValueKind.Array)
                    throw new RulesFormatException("\"steps\" must be an array");

                int n = 0;
                foreach (var el in steps.EnumerateArray())
                {
                    n++;
                    if (el.ValueKind != JsonValueKind.Object)
                        throw new RulesFormatException($"step {n} must be an object");
                    rules.Steps.Add(ParseStep(el, n));
                }
            }

            return rules;
        }
    }

    private static RuleStep ParseStep(JsonElement el, int n)
    {
        if (!el.TryGetProperty("op", out var opEl) || opEl.ValueKind != JsonValueKind.String)
            throw new RulesFormatException($"step {n} is missing a string \"op\"");

        string op = opEl.GetString()!.Trim().ToLowerInvariant();
        var step = new RuleStep();

        switch (op)
        {
            case "replace":
                step.Op = StepOp.Replace;
                step.Find = Str(el, "find", "");
                step.ReplaceWith = Str(el, "replaceWith", "");
                step.Regex = Bool(el, "regex", false);
                step.IgnoreCase = Bool(el, "ignoreCase", false);
                break;

            case "insert":
                step.Op = StepOp.Insert;
                step.Text = Str(el, "text", "");
                step.Position = ReadEnum(el, "position", InsertPosition.Prefix, new()
                {
                    ["prefix"] = InsertPosition.Prefix,
                    ["suffix"] = InsertPosition.Suffix,
                    ["index"] = InsertPosition.Index,
                }, n);
                step.Index = (int)Math.Clamp(Num(el, "index", 0), int.MinValue, int.MaxValue);
                break;

            case "remove":
                step.Op = StepOp.Remove;
                step.From = (int)Math.Clamp(Num(el, "from", 0), int.MinValue, int.MaxValue);
                step.Count = (int)Math.Clamp(Num(el, "count", 0), int.MinValue, int.MaxValue);
                break;

            case "sequence":
                step.Op = StepOp.Sequence;
                step.Pattern = Str(el, "pattern", "{n:000}");
                step.Start = Num(el, "start", 1);
                step.Step = Num(el, "step", 1);
                step.SeqPosition = ReadEnum(el, "position", SequencePosition.Prefix, new()
                {
                    ["prefix"] = SequencePosition.Prefix,
                    ["suffix"] = SequencePosition.Suffix,
                }, n);
                break;

            case "case":
                step.Op = StepOp.Case;
                step.CaseMode = ReadEnum(el, "mode", CaseMode.Lower, new()
                {
                    ["upper"] = CaseMode.Upper,
                    ["lower"] = CaseMode.Lower,
                    ["title"] = CaseMode.Title,
                }, n);
                break;

            case "extension":
                step.Op = StepOp.Extension;
                step.ExtensionMode = ReadEnum(el, "mode", ExtensionMode.Lower, new()
                {
                    ["lower"] = ExtensionMode.Lower,
                    ["upper"] = ExtensionMode.Upper,
                    ["set"] = ExtensionMode.Set,
                }, n);
                step.Value = Str(el, "value", "");
                break;

            default:
                throw new RulesFormatException($"step {n}: unknown op \"{op}\"");
        }

        return step;
    }

    // ---- primitive readers -------------------------------------------------

    private static string Str(JsonElement el, string name, string fallback)
    {
        if (!el.TryGetProperty(name, out var v) || v.ValueKind == JsonValueKind.Null) return fallback;
        if (v.ValueKind != JsonValueKind.String)
            throw new RulesFormatException($"\"{name}\" must be a string");
        return v.GetString() ?? fallback;
    }

    private static bool Bool(JsonElement el, string name, bool fallback)
    {
        if (!el.TryGetProperty(name, out var v) || v.ValueKind == JsonValueKind.Null) return fallback;
        return v.ValueKind switch
        {
            JsonValueKind.True => true,
            JsonValueKind.False => false,
            _ => throw new RulesFormatException($"\"{name}\" must be true or false"),
        };
    }

    private static long Num(JsonElement el, string name, long fallback)
    {
        if (!el.TryGetProperty(name, out var v) || v.ValueKind == JsonValueKind.Null) return fallback;
        if (v.ValueKind != JsonValueKind.Number || !v.TryGetInt64(out long n))
            throw new RulesFormatException($"\"{name}\" must be an integer");
        return n;
    }

    private static T ReadEnum<T>(JsonElement el, string name, T fallback, Dictionary<string, T> map, int? stepNo = null)
        where T : struct, Enum
    {
        if (!el.TryGetProperty(name, out var v) || v.ValueKind == JsonValueKind.Null) return fallback;
        if (v.ValueKind != JsonValueKind.String)
            throw new RulesFormatException($"\"{name}\" must be a string");

        string key = v.GetString()!.Trim().ToLowerInvariant();
        if (map.TryGetValue(key, out var result)) return result;

        string where = stepNo is null ? "" : $"step {stepNo}: ";
        throw new RulesFormatException(
            $"{where}\"{name}\" must be one of {string.Join(" | ", map.Keys)} (got \"{v.GetString()}\")");
    }

    // ---- writing -----------------------------------------------------------

    /// <summary>Serialises a rule set back to the contract shape. Disabled steps are omitted.</summary>
    public static string Serialize(RuleSet rules)
    {
        var buffer = new MemoryStream();
        using (var w = new Utf8JsonWriter(buffer, new JsonWriterOptions
        {
            Indented = true,
            Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping,
        }))
        {
            w.WriteStartObject();
            w.WriteString("applyTo", rules.ApplyTo == ApplyTo.NameAndExtension ? "nameAndExtension" : "name");
            w.WriteString("sort", rules.Sort switch
            {
                SortMode.Created => "created",
                SortMode.Modified => "modified",
                _ => "name",
            });
            w.WriteStartArray("steps");
            foreach (var s in rules.Steps)
            {
                if (!s.Enabled) continue;
                w.WriteStartObject();
                switch (s.Op)
                {
                    case StepOp.Replace:
                        w.WriteString("op", "replace");
                        w.WriteString("find", s.Find);
                        w.WriteString("replaceWith", s.ReplaceWith);
                        w.WriteBoolean("regex", s.Regex);
                        w.WriteBoolean("ignoreCase", s.IgnoreCase);
                        break;
                    case StepOp.Insert:
                        w.WriteString("op", "insert");
                        w.WriteString("text", s.Text);
                        w.WriteString("position", s.Position switch
                        {
                            InsertPosition.Suffix => "suffix",
                            InsertPosition.Index => "index",
                            _ => "prefix",
                        });
                        w.WriteNumber("index", s.Index);
                        break;
                    case StepOp.Remove:
                        w.WriteString("op", "remove");
                        w.WriteNumber("from", s.From);
                        w.WriteNumber("count", s.Count);
                        break;
                    case StepOp.Sequence:
                        w.WriteString("op", "sequence");
                        w.WriteString("pattern", s.Pattern);
                        w.WriteNumber("start", s.Start);
                        w.WriteNumber("step", s.Step);
                        w.WriteString("position", s.SeqPosition == SequencePosition.Suffix ? "suffix" : "prefix");
                        break;
                    case StepOp.Case:
                        w.WriteString("op", "case");
                        w.WriteString("mode", s.CaseMode switch
                        {
                            CaseMode.Upper => "upper",
                            CaseMode.Title => "title",
                            _ => "lower",
                        });
                        break;
                    case StepOp.Extension:
                        w.WriteString("op", "extension");
                        w.WriteString("mode", s.ExtensionMode switch
                        {
                            ExtensionMode.Upper => "upper",
                            ExtensionMode.Set => "set",
                            _ => "lower",
                        });
                        w.WriteString("value", s.Value);
                        break;
                }
                w.WriteEndObject();
            }
            w.WriteEndArray();
            w.WriteEndObject();
        }

        return JsonText.Normalize(Encoding.UTF8.GetString(buffer.ToArray()));
    }

    public static void Save(string path, RuleSet rules) =>
        JsonText.WriteUtf8NoBom(path, Serialize(rules));
}

