using System.Text;
using System.Text.Encodings.Web;
using System.Text.Json;

namespace BatchRenameStudio.Core;

/// <summary>Shared text conventions for every JSON file this tool writes.</summary>
public static class JsonText
{
    private static readonly UTF8Encoding Utf8NoBom = new(encoderShouldEmitUTF8Identifier: false);

    /// <summary>
    /// LF line endings and exactly one trailing newline, so the same inputs always produce
    /// byte-identical output regardless of platform (contract rule 15).
    /// </summary>
    public static string Normalize(string json)
    {
        json = json.Replace("\r\n", "\n").Replace('\r', '\n');
        return json.TrimEnd('\n') + "\n";
    }

    /// <summary>Writes UTF-8 without a byte order mark.</summary>
    public static void WriteUtf8NoBom(string path, string text)
    {
        string? dir = Path.GetDirectoryName(Path.GetFullPath(path));
        if (!string.IsNullOrEmpty(dir)) Directory.CreateDirectory(dir);
        File.WriteAllText(path, text, Utf8NoBom);
    }

    public static JsonWriterOptions WriterOptions => new()
    {
        Indented = true,
        Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping,
    };
}

/// <summary>Writer for the fixed <c>plan.json</c> contract.</summary>
public static class PlanJson
{
    public static string Serialize(RenamePlan plan)
    {
        var buffer = new MemoryStream();
        using (var w = new Utf8JsonWriter(buffer, JsonText.WriterOptions))
        {
            w.WriteStartObject();
            w.WriteNumber("schemaVersion", plan.SchemaVersion);

            w.WriteStartArray("items");
            foreach (var item in plan.Items)
            {
                w.WriteStartObject();
                w.WriteString("original", item.Original);
                w.WriteString("proposed", item.Proposed);
