namespace BatchRenameStudio.Core;

/// <summary>Reads the (non-recursive) file listing the engine works on.</summary>
public static class FolderScanner
{
    /// <summary>
    /// Contract rule 1: only files directly inside <paramref name="folder"/>. Sub-directories are
    /// excluded entirely and never descended into.
    /// </summary>
    public static List<FileEntry> Scan(string folder)
    {
        var dir = new DirectoryInfo(folder);
        if (!dir.Exists) throw new DirectoryNotFoundException($"folder not found: {folder}");

        var result = new List<FileEntry>();
        foreach (var f in dir.EnumerateFiles("*", SearchOption.TopDirectoryOnly))
        {
            result.Add(new FileEntry(f.Name, f.CreationTimeUtc, f.LastWriteTimeUtc));
        }
        return result;
    }
}

