using System.Text;
using System.Text.Json;

namespace BatchRenameStudio.Core;

/// <summary>One executed rename, stored so it can be reverted.</summary>
public sealed record RenamePair(string From, string To);

/// <summary>An applied batch: everything needed to put the folder back the way it was.</summary>
public sealed class UndoBatch
{
    public required string Folder { get; init; }
    public required DateTime AppliedUtc { get; init; }
    public required List<RenamePair> Pairs { get; init; }

    /// <summary>The reverse operation: rename each new name back to its old name.</summary>
    public List<RenamePair> Inverse() => Pairs.Select(p => new RenamePair(p.To, p.From)).Reverse().ToList();
}

public sealed class RenameFailedException : Exception
{
    public RenameFailedException(string message, Exception? inner = null) : base(message, inner) { }
}

/// <summary>
/// Executes a set of renames inside one folder. Every batch runs in two phases
/// (original -&gt; unique temp -&gt; final) so that swaps and rotation cycles such as
/// a-&gt;b, b-&gt;a work, and so a mid-way failure can be rolled back completely.
/// </summary>
public static class Renamer
{
    /// <summary>Applies the "ok" items of a plan. Returns the batch that undoes it.</summary>
    public static UndoBatch ApplyPlan(string folder, IEnumerable<PlanItem> items)
    {
        var pairs = items
            .Where(i => i.Status == PlanStatus.Ok)
            .Select(i => new RenamePair(i.Original, i.Proposed))
            .ToList();
        return Execute(folder, pairs);
    }

    /// <summary>Runs the given renames, rolling everything back if any single step fails.</summary>
    public static UndoBatch Execute(string folder, IReadOnlyList<RenamePair> pairs)
    {
        var done = new List<(string TempPath, string FinalPath, string OriginalPath)>();

        // Phase 1: move every source out of the way to a name nothing can collide with.
        try
        {
            for (int i = 0; i < pairs.Count; i++)
            {
                string originalPath = Path.Combine(folder, pairs[i].From);
                string tempPath = Path.Combine(folder, TempName(i));
                File.Move(originalPath, tempPath);
                done.Add((tempPath, Path.Combine(folder, pairs[i].To), originalPath));
            }
        }
        catch (Exception ex)
        {
            RollbackPhase1(done);
            throw new RenameFailedException($"rename failed and was rolled back: {ex.Message}", ex);
        }

        // Phase 2: move each temp file to its final name.
        int completed = 0;
        try
        {
            for (; completed < done.Count; completed++)
            {
                File.Move(done[completed].TempPath, done[completed].FinalPath);
            }
        }
        catch (Exception ex)
        {
            for (int i = completed - 1; i >= 0; i--)
            {
                TryMove(done[i].FinalPath, done[i].TempPath);
            }
            RollbackPhase1(done);
            throw new RenameFailedException($"rename failed and was rolled back: {ex.Message}", ex);
        }

        return new UndoBatch
        {
            Folder = folder,
            AppliedUtc = DateTime.UtcNow,
            Pairs = pairs.ToList(),
        };
    }

    private static void RollbackPhase1(List<(string TempPath, string FinalPath, string OriginalPath)> done)
    {
        for (int i = done.Count - 1; i >= 0; i--) TryMove(done[i].TempPath, done[i].OriginalPath);
    }

    private static void TryMove(string from, string to)
    {
        try
        {
            if (File.Exists(from)) File.Move(from, to);
        }
        catch
        {
            // Best effort: the caller is already reporting a failure.
        }
    }

    private static string TempName(int index) =>
        $"brs-tmp-{Guid.NewGuid():N}-{index:0000}";

    // ---- undo history on disk ---------------------------------------------

    public static string HistoryFolder => Path.Combine(
        Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
        "BatchRenameStudio", "undo");

    /// <summary>Persists a batch so it can still be reverted after the app is closed.</summary>
    public static string SaveHistory(UndoBatch batch)
    {
        Directory.CreateDirectory(HistoryFolder);
        string path = Path.Combine(HistoryFolder,
            $"undo-{batch.AppliedUtc:yyyyMMdd-HHmmss-fff}.json");

        var buffer = new MemoryStream();
        using (var w = new Utf8JsonWriter(buffer, JsonText.WriterOptions))
        {
            w.WriteStartObject();
            w.WriteNumber("schemaVersion", 1);
            w.WriteString("folder", batch.Folder);
            w.WriteString("appliedUtc", batch.AppliedUtc.ToString("o"));
            w.WriteStartArray("renames");
            foreach (var p in batch.Pairs)
            {
                w.WriteStartObject();
                w.WriteString("from", p.From);
                w.WriteString("to", p.To);
                w.WriteEndObject();
            }
            w.WriteEndArray();
            w.WriteEndObject();
        }

        JsonText.WriteUtf8NoBom(path, JsonText.Normalize(Encoding.UTF8.GetString(buffer.ToArray())));
        return path;
    }

    public static UndoBatch LoadHistory(string path)
    {
        using var doc = JsonDocument.Parse(File.ReadAllText(path));
        var root = doc.RootElement;
        var pairs = new List<RenamePair>();
        if (root.TryGetProperty("renames", out var arr) && arr.ValueKind == JsonValueKind.Array)
        {
            foreach (var el in arr.EnumerateArray())
            {
                pairs.Add(new RenamePair(
                    el.GetProperty("from").GetString() ?? "",
                    el.GetProperty("to").GetString() ?? ""));
            }
        }

        return new UndoBatch
        {
            Folder = root.TryGetProperty("folder", out var f) ? f.GetString() ?? "" : "",
            AppliedUtc = root.TryGetProperty("appliedUtc", out var t) && t.TryGetDateTime(out var dt)
                ? dt
                : DateTime.UtcNow,
            Pairs = pairs,
        };
    }
}

