using System.Runtime.InteropServices;
using System.Text;

namespace BatchRenameStudio.Cli;

/// <summary>
/// A WinForms executable is a GUI-subsystem binary, so it starts with no console attached and
/// <see cref="Console"/> silently swallows output. This attaches the parent console (or keeps the
/// already-redirected pipe/file handles) so the headless <c>--plan</c> mode can actually print.
/// </summary>
internal static class ConsoleBridge
{
    private const int AttachParentProcess = -1;
    private const int StdOutputHandle = -11;
    private const int StdErrorHandle = -12;

    private static bool _attached;

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern bool AttachConsole(int dwProcessId);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern bool FreeConsole();

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern IntPtr GetStdHandle(int nStdHandle);

    public static void Attach()
    {
        // When the launcher redirected stdout (a pipe or a file) the handle is already valid and
        // inherited; attaching a console in that case would be pointless, so only attach if needed.
        bool needConsole = !IsValid(GetStdHandle(StdOutputHandle)) || !IsValid(GetStdHandle(StdErrorHandle));
        if (needConsole)
        {
            _attached = AttachConsole(AttachParentProcess);
        }

        Rebind(StdOutputHandle, Console.SetOut, Console.OpenStandardOutput);
        Rebind(StdErrorHandle, Console.SetError, Console.OpenStandardError);
    }

    private static void Rebind(int handleId, Action<TextWriter> set, Func<Stream> open)
    {
        try
        {
            if (!IsValid(GetStdHandle(handleId))) return;
            var stream = open();
            if (stream == Stream.Null) return;
            set(new StreamWriter(stream, new UTF8Encoding(false)) { AutoFlush = true });
        }
        catch (IOException)
        {
            // No usable stream: stay with the default (null) writer rather than crash.
        }
    }

    public static void Detach()
    {
        try
        {
            Console.Out.Flush();
            Console.Error.Flush();
        }
        catch (IOException)
        {
            // Nothing to flush.
        }

        if (_attached) FreeConsole();
    }

    private static bool IsValid(IntPtr h) => h != IntPtr.Zero && h != new IntPtr(-1);
}

