using System.Globalization;
using BatchRenameStudio.Core;

namespace BatchRenameStudio.Cli;

/// <summary>Exit codes of the headless mode. 0 means the plan file was written.</summary>
internal static class ExitCodes
{
    public const int Success = 0;
    public const int Usage = 2;
    public const int BadRules = 3;
    public const int Io = 4;
}

/// <summary>
/// The fixed headless contract:
/// <c>BatchRenameStudio.exe --plan --dir &lt;folder&gt; --rules &lt;rules.json&gt; --out &lt;plan.json&gt;</c>.
/// Writes the plan, prints one summary line, renames nothing.
/// </summary>
internal static class PlanCommand
{
    public const string Usage =
        "usage: BatchRenameStudio.exe --plan --dir <folder> --rules <rules.json> --out <plan.json>";

    /// <summary>True when the process was started for the headless planner rather than the GUI.</summary>
    public static bool IsRequested(string[] args) =>
        args.Any(a => string.Equals(a, "--plan", StringComparison.OrdinalIgnoreCase));

    public static bool IsHelpRequested(string[] args) =>
        args.Any(a => a is "--help" or "-h" or "-?" or "/?");

    public static int Run(string[] args)
    {
        string? dir = null, rulesPath = null, outPath = null;

        for (int i = 0; i < args.Length; i++)
        {
            string arg = args[i];
            if (string.Equals(arg, "--plan", StringComparison.OrdinalIgnoreCase)) continue;

            string name = arg, inline = "";
            int eq = arg.IndexOf('=');
            bool hasInline = arg.StartsWith("--", StringComparison.Ordinal) && eq > 0;
            if (hasInline)
            {
                name = arg[..eq];
                inline = arg[(eq + 1)..];
            }

            switch (name.ToLowerInvariant())
            {
                case "--dir":
                    if (!TryValue(args, ref i, hasInline, inline, out dir)) return Fail("--dir needs a value");
                    break;
                case "--rules":
                    if (!TryValue(args, ref i, hasInline, inline, out rulesPath)) return Fail("--rules needs a value");
                    break;
                case "--out":
                    if (!TryValue(args, ref i, hasInline, inline, out outPath)) return Fail("--out needs a value");
                    break;
                default:
                    return Fail($"unknown argument \"{arg}\"");
            }
        }

        if (string.IsNullOrWhiteSpace(dir)) return Fail("--dir is required");
        if (string.IsNullOrWhiteSpace(rulesPath)) return Fail("--rules is required");
        if (string.IsNullOrWhiteSpace(outPath)) return Fail("--out is required");

        RuleSet rules;
        try
        {
            rules = RulesJson.Load(rulesPath!);
        }
        catch (RulesFormatException ex)
        {
            return Error(ExitCodes.BadRules, ex.Message);
        }
        catch (FileNotFoundException)
        {
            return Error(ExitCodes.BadRules, $"rules file not found: {rulesPath}");
        }

        List<FileEntry> files;
        try
        {
            files = FolderScanner.Scan(dir!);
        }
        catch (DirectoryNotFoundException)
        {
            return Error(ExitCodes.Io, $"folder not found: {dir}");
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            return Error(ExitCodes.Io, $"cannot read folder \"{dir}\": {ex.Message}");
        }

        RenamePlan plan;
        try
        {
            plan = RenameEngine.BuildPlan(files, rules);
        }
        catch (RuleException ex)
        {
            return Error(ExitCodes.BadRules, ex.Message);
        }

        try
        {
            PlanJson.Save(outPath!, plan);
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            return Error(ExitCodes.Io, $"cannot write plan \"{outPath}\": {ex.Message}");
        }

        var s = plan.Summary;
        Console.Out.WriteLine(string.Create(CultureInfo.InvariantCulture,
            $"plan: total={s.Total} ok={s.Ok} collision={s.Collision} unchanged={s.Unchanged} invalid={s.Invalid} -> {Path.GetFullPath(outPath!)}"));
        return ExitCodes.Success;
    }

    private static bool TryValue(string[] args, ref int i, bool hasInline, string inline, out string? value)
    {
        if (hasInline)
        {
            value = inline;
            return value.Length > 0;
        }
        if (i + 1 >= args.Length)
        {
            value = null;
            return false;
        }
        value = args[++i];
        return true;
    }

    private static int Fail(string message)
    {
        Console.Error.WriteLine($"error: {message}");
        Console.Error.WriteLine(Usage);
        return ExitCodes.Usage;
    }

    private static int Error(int code, string message)
    {
        Console.Error.WriteLine($"error: {message}");
        return code;
    }
}

