using BatchRenameStudio.Core;

namespace BatchRenameStudio.Ui;

/// <summary>Presentation helpers shared by the step list and the step editor.</summary>
internal static class StepUi
{
    public static string OpTitle(StepOp op) => op switch
    {
        StepOp.Replace => "Replace text",
        StepOp.Insert => "Insert text",
        StepOp.Remove => "Remove characters",
        StepOp.Sequence => "Numbering",
        StepOp.Case => "Change case",
        StepOp.Extension => "Extension",
        _ => op.ToString(),
    };

    /// <summary>One-line human summary of a step, shown in the rule list.</summary>
    public static string Describe(RuleStep s) => s.Op switch
    {
        StepOp.Replace =>
            $"Replace {(s.Regex ? "regex " : "")}\"{s.Find}\" -> \"{s.ReplaceWith}\"{(s.IgnoreCase ? " (ignore case)" : "")}",
        StepOp.Insert => s.Position switch
        {
            InsertPosition.Prefix => $"Insert \"{s.Text}\" at the start",
            InsertPosition.Suffix => $"Insert \"{s.Text}\" at the end",
            _ => $"Insert \"{s.Text}\" at index {s.Index}",
        },
        StepOp.Remove => $"Remove {s.Count} char(s) from index {s.From}",
        StepOp.Sequence =>
            $"Number \"{s.Pattern}\" as {(s.SeqPosition == SequencePosition.Suffix ? "suffix" : "prefix")}, start {s.Start} step {s.Step}",
        StepOp.Case => $"Case -> {s.CaseMode.ToString().ToLowerInvariant()}",
        StepOp.Extension => s.ExtensionMode == ExtensionMode.Set
            ? $"Extension -> set \"{s.Value}\""
            : $"Extension -> {s.ExtensionMode.ToString().ToLowerInvariant()}",
        _ => s.Op.ToString(),
    };

    /// <summary>Wrapper so a <see cref="CheckedListBox"/> can show a step and keep a reference to it.</summary>
    public sealed class StepBox
    {
        public StepBox(RuleStep step) => Step = step;

        public RuleStep Step { get; }

        public override string ToString() => Describe(Step);
    }
}

