using BatchRenameStudio.Core;

namespace BatchRenameStudio.Ui;

/// <summary>
/// The whole GUI: pick a folder, stack up rule steps, watch the live preview, apply, undo.
/// The preview is produced by the very same <see cref="RenameEngine"/> the headless planner uses,
/// so what the window shows is exactly what <c>--plan</c> would write.
/// </summary>
internal sealed class MainForm : Form
{
    private readonly RuleSet _rules = new();
    private readonly List<FileEntry> _files = new();
    private readonly Stack<UndoBatch> _undo = new();
    private RenamePlan? _plan;

    private string _folder = "";
    private bool _suspendPreview;

    private readonly TextBox _folderBox = new();
    private readonly ComboBox _applyToBox = new();
    private readonly ComboBox _sortBox = new();
    private readonly CheckedListBox _stepList = new();
    private readonly ListView _preview = new();
    private readonly StatusStrip _status = new();
    private readonly ToolStripStatusLabel _counts = new();
    private readonly ToolStripStatusLabel _message = new();
    private readonly Button _applyButton = new();
    private readonly Button _undoButton = new();

    public MainForm(string? initialFolder)
    {
        Text = "Batch Rename Studio";
        MinimumSize = new Size(900, 560);
        ClientSize = new Size(1120, 680);
        StartPosition = FormStartPosition.CenterScreen;

        BuildLayout();

        if (!string.IsNullOrWhiteSpace(initialFolder) && Directory.Exists(initialFolder))
        {
            SetFolder(initialFolder!);
        }
        else
        {
            RefreshPreview();
        }
    }

    // ---- layout ------------------------------------------------------------

    private void BuildLayout()
    {
        var split = new SplitContainer
        {
            Dock = DockStyle.Fill,
            SplitterDistance = 380,
            FixedPanel = FixedPanel.Panel1,
        };
        split.Panel1.Controls.Add(BuildStepPanel());
        split.Panel2.Controls.Add(BuildPreviewPanel());

        Controls.Add(split);
        Controls.Add(BuildTopPanel());
        Controls.Add(BuildMenu());
        Controls.Add(BuildActionPanel());
        Controls.Add(BuildStatusBar());

        // SplitterDistance only sticks once the control has a size.
        Shown += (_, _) => split.SplitterDistance = 380;
    }

    private MenuStrip BuildMenu()
    {
        var menu = new MenuStrip();

        var file = new ToolStripMenuItem("&File");
        file.DropDownItems.Add("Open folder...", null, (_, _) => BrowseFolder());
        file.DropDownItems.Add("Rescan folder", null, (_, _) => Rescan());
        file.DropDownItems.Add(new ToolStripSeparator());
        file.DropDownItems.Add("Load rules...", null, (_, _) => LoadRules());
        file.DropDownItems.Add("Save rules as...", null, (_, _) => SaveRules());
        file.DropDownItems.Add("Export plan.json...", null, (_, _) => ExportPlan());
        file.DropDownItems.Add(new ToolStripSeparator());
        file.DropDownItems.Add("Exit", null, (_, _) => Close());

        var steps = new ToolStripMenuItem("&Steps");
        var add = new ToolStripMenuItem("Add step");
        foreach (StepOp op in Enum.GetValues<StepOp>())
        {
            var captured = op;
            add.DropDownItems.Add(StepUi.OpTitle(op), null, (_, _) => AddStep(captured));
        }
        steps.DropDownItems.Add(add);
        steps.DropDownItems.Add("Edit selected", null, (_, _) => EditSelectedStep());
        steps.DropDownItems.Add("Remove selected", null, (_, _) => RemoveSelectedStep());
        steps.DropDownItems.Add(new ToolStripSeparator());
        steps.DropDownItems.Add("Move up", null, (_, _) => MoveStep(-1));
        steps.DropDownItems.Add("Move down", null, (_, _) => MoveStep(1));
        steps.DropDownItems.Add("Clear all", null, (_, _) => ClearSteps());

        var tools = new ToolStripMenuItem("&Tools");
        tools.DropDownItems.Add("Apply rename", null, (_, _) => ApplyRename());
        tools.DropDownItems.Add("Undo last rename", null, (_, _) => UndoLast());
        tools.DropDownItems.Add("Undo from log file...", null, (_, _) => UndoFromLog());
        tools.DropDownItems.Add(new ToolStripSeparator());
        tools.DropDownItems.Add("Open undo log folder", null, (_, _) => OpenHistoryFolder());

        var help = new ToolStripMenuItem("&Help");
        help.DropDownItems.Add("About", null, (_, _) => ShowAbout());

        menu.Items.AddRange(new ToolStripItem[] { file, steps, tools, help });
        MainMenuStrip = menu;
        return menu;
    }

    private Control BuildTopPanel()
    {
        var panel = new TableLayoutPanel
        {
            Dock = DockStyle.Top,
            Height = 68,
            ColumnCount = 6,
            RowCount = 2,
            Padding = new Padding(8, 6, 8, 4),
        };
        panel.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute, 60));
        panel.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 100));
        panel.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute, 90));
        panel.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute, 90));
        panel.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute, 150));
        panel.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute, 150));

        panel.Controls.Add(new Label { Text = "Folder", Dock = DockStyle.Fill, TextAlign = ContentAlignment.MiddleLeft }, 0, 0);

        _folderBox.Dock = DockStyle.Fill;
        _folderBox.PlaceholderText = "Pick a folder to rename files in";
        _folderBox.KeyDown += (_, e) =>
        {
            if (e.KeyCode != Keys.Enter) return;
            e.SuppressKeyPress = true;
            SetFolder(_folderBox.Text.Trim());
        };
        panel.Controls.Add(_folderBox, 1, 0);

        var browse = new Button { Text = "Browse...", Dock = DockStyle.Fill };
        browse.Click += (_, _) => BrowseFolder();
        panel.Controls.Add(browse, 2, 0);

        var rescan = new Button { Text = "Rescan", Dock = DockStyle.Fill };
        rescan.Click += (_, _) => Rescan();
        panel.Controls.Add(rescan, 3, 0);

        panel.Controls.Add(new Label { Text = "Apply to", Dock = DockStyle.Fill, TextAlign = ContentAlignment.MiddleRight }, 0, 1);

        _applyToBox.DropDownStyle = ComboBoxStyle.DropDownList;
        _applyToBox.Items.AddRange(new object[] { "name (without extension)", "name and extension" });
        _applyToBox.SelectedIndex = 0;
        _applyToBox.Width = 200;
        _applyToBox.SelectedIndexChanged += (_, _) =>
        {
            _rules.ApplyTo = _applyToBox.SelectedIndex == 1 ? ApplyTo.NameAndExtension : ApplyTo.Name;
            RefreshPreview();
        };
        panel.Controls.Add(_applyToBox, 1, 1);

        _sortBox.DropDownStyle = ComboBoxStyle.DropDownList;
        _sortBox.Items.AddRange(new object[] { "sort: name", "sort: created", "sort: modified" });
        _sortBox.SelectedIndex = 0;
        _sortBox.Dock = DockStyle.Fill;
        _sortBox.SelectedIndexChanged += (_, _) =>
        {
            _rules.Sort = (SortMode)_sortBox.SelectedIndex;
            RefreshPreview();
        };
        panel.Controls.Add(_sortBox, 2, 1);
        panel.SetColumnSpan(_sortBox, 2);

        return panel;
    }

    private Control BuildStepPanel()
    {
        var host = new Panel { Dock = DockStyle.Fill, Padding = new Padding(8, 8, 4, 8) };

        _stepList.Dock = DockStyle.Fill;
        _stepList.CheckOnClick = true;
        _stepList.IntegralHeight = false;
        _stepList.DoubleClick += (_, _) => EditSelectedStep();
        _stepList.ItemCheck += (_, e) =>
        {
            if (_stepList.Items[e.Index] is StepUi.StepBox box)
            {
                box.Step.Enabled = e.NewValue == CheckState.Checked;
                BeginInvoke(new Action(RefreshPreview));
            }
        };

        var buttons = new FlowLayoutPanel
        {
            Dock = DockStyle.Bottom,
            Height = 40,
            FlowDirection = FlowDirection.LeftToRight,
            Padding = new Padding(0, 6, 0, 0),
        };

        var addButton = new Button { Text = "Add step", Width = 90 };
        var addMenu = new ContextMenuStrip();
        foreach (StepOp op in Enum.GetValues<StepOp>())
        {
            var captured = op;
            addMenu.Items.Add(StepUi.OpTitle(op), null, (_, _) => AddStep(captured));
        }
        addButton.Click += (_, _) => addMenu.Show(addButton, new Point(0, addButton.Height));

        buttons.Controls.Add(addButton);
        buttons.Controls.Add(MakeButton("Edit", 70, EditSelectedStep));
        buttons.Controls.Add(MakeButton("Remove", 80, RemoveSelectedStep));
        buttons.Controls.Add(MakeButton("Up", 55, () => MoveStep(-1)));
        buttons.Controls.Add(MakeButton("Down", 60, () => MoveStep(1)));

        var header = new Label
        {
            Dock = DockStyle.Top,
            Height = 22,
            Text = "Rules (applied top to bottom; uncheck to disable)",
            TextAlign = ContentAlignment.MiddleLeft,
        };

        host.Controls.Add(_stepList);
        host.Controls.Add(header);
        host.Controls.Add(buttons);
        return host;
    }

    private static Button MakeButton(string text, int width, Action onClick)
    {
        var b = new Button { Text = text, Width = width };
        b.Click += (_, _) => onClick();
        return b;
    }

    private Control BuildPreviewPanel()
    {
        var host = new Panel { Dock = DockStyle.Fill, Padding = new Padding(4, 8, 8, 8) };

        _preview.Dock = DockStyle.Fill;
        _preview.View = View.Details;
        _preview.FullRowSelect = true;
        _preview.GridLines = true;
        _preview.HideSelection = false;
        _preview.Columns.Add("#", 40, HorizontalAlignment.Right);
        _preview.Columns.Add("Original", 260);
        _preview.Columns.Add("Proposed", 260);
        _preview.Columns.Add("Status", 90);
        _preview.Columns.Add("Reason", 220);

        var header = new Label
        {
            Dock = DockStyle.Top,
            Height = 22,
            Text = "Preview (rows are listed in processing order)",
            TextAlign = ContentAlignment.MiddleLeft,
        };

        host.Controls.Add(_preview);
        host.Controls.Add(header);
        return host;
    }

    private Control BuildActionPanel()
    {
        var panel = new FlowLayoutPanel
        {
            Dock = DockStyle.Bottom,
            Height = 46,
            FlowDirection = FlowDirection.RightToLeft,
            Padding = new Padding(8, 6, 8, 6),
        };

        _applyButton.Text = "Apply rename";
        _applyButton.Width = 130;
        _applyButton.Height = 30;
        _applyButton.Click += (_, _) => ApplyRename();

        _undoButton.Text = "Undo last";
        _undoButton.Width = 100;
        _undoButton.Height = 30;
        _undoButton.Enabled = false;
        _undoButton.Click += (_, _) => UndoLast();

        panel.Controls.Add(_applyButton);
        panel.Controls.Add(_undoButton);
        return panel;
    }

    private Control BuildStatusBar()
    {
        _counts.Text = "no folder";
        _message.Spring = true;
        _message.TextAlign = ContentAlignment.MiddleLeft;
        _status.Items.Add(_counts);
        _status.Items.Add(new ToolStripSeparator());
        _status.Items.Add(_message);
        return _status;
    }

    // ---- folder ------------------------------------------------------------

    private void BrowseFolder()
    {
        using var dialog = new FolderBrowserDialog { ShowNewFolderButton = false };
        if (Directory.Exists(_folder)) dialog.SelectedPath = _folder;
        if (dialog.ShowDialog(this) == DialogResult.OK) SetFolder(dialog.SelectedPath);
    }

    private void SetFolder(string folder)
    {
        if (!Directory.Exists(folder))
        {
            Warn($"Folder not found:\n{folder}");
            return;
        }

        _folder = folder;
        _folderBox.Text = folder;
        _undo.Clear();
        _undoButton.Enabled = false;
        Rescan();
    }

    private void Rescan()
    {
        _files.Clear();
        if (Directory.Exists(_folder))
        {
            try
            {
                _files.AddRange(FolderScanner.Scan(_folder));
            }
            catch (Exception ex)
            {
                Warn($"Cannot read the folder:\n{ex.Message}");
            }
        }
        RefreshPreview();
    }

    // ---- steps -------------------------------------------------------------

    private void AddStep(StepOp op)
    {
        var step = Defaults(op);
        using var editor = new StepEditorForm(step);
        if (editor.ShowDialog(this) != DialogResult.OK) return;

        _rules.Steps.Add(editor.Result);
        RefreshStepList(_rules.Steps.Count - 1);
    }

    private static RuleStep Defaults(StepOp op) => op switch
    {
        StepOp.Replace => new RuleStep { Op = op, Find = "", ReplaceWith = "" },
        StepOp.Insert => new RuleStep { Op = op, Text = "", Position = InsertPosition.Prefix },
        StepOp.Remove => new RuleStep { Op = op, From = 0, Count = 1 },
        StepOp.Sequence => new RuleStep { Op = op, Pattern = "{n:000}_", Start = 1, Step = 1 },
        StepOp.Case => new RuleStep { Op = op, CaseMode = CaseMode.Lower },
        StepOp.Extension => new RuleStep { Op = op, ExtensionMode = ExtensionMode.Lower },
        _ => new RuleStep { Op = op },
    };

    private void EditSelectedStep()
    {
        int i = _stepList.SelectedIndex;
        if (i < 0) return;

        using var editor = new StepEditorForm(_rules.Steps[i]);
        if (editor.ShowDialog(this) != DialogResult.OK) return;

        var edited = editor.Result;
        edited.Enabled = _rules.Steps[i].Enabled;
        _rules.Steps[i] = edited;
        RefreshStepList(i);
    }

    private void RemoveSelectedStep()
    {
        int i = _stepList.SelectedIndex;
        if (i < 0) return;
        _rules.Steps.RemoveAt(i);
        RefreshStepList(Math.Min(i, _rules.Steps.Count - 1));
    }

    private void MoveStep(int delta)
    {
        int i = _stepList.SelectedIndex;
        int j = i + delta;
        if (i < 0 || j < 0 || j >= _rules.Steps.Count) return;

        (_rules.Steps[i], _rules.Steps[j]) = (_rules.Steps[j], _rules.Steps[i]);
        RefreshStepList(j);
    }

    private void ClearSteps()
    {
        if (_rules.Steps.Count == 0) return;
        if (MessageBox.Show(this, "Remove every rule step?", "Batch Rename Studio",
                MessageBoxButtons.YesNo, MessageBoxIcon.Question) != DialogResult.Yes) return;
        _rules.Steps.Clear();
        RefreshStepList(-1);
    }

    private void RefreshStepList(int select)
    {
        _suspendPreview = true;
        _stepList.BeginUpdate();
        _stepList.Items.Clear();
        foreach (var step in _rules.Steps)
        {
            _stepList.Items.Add(new StepUi.StepBox(step), step.Enabled);
        }
        _stepList.EndUpdate();
        _suspendPreview = false;

        if (select >= 0 && select < _stepList.Items.Count) _stepList.SelectedIndex = select;
        RefreshPreview();
    }

    // ---- preview -----------------------------------------------------------

    private void RefreshPreview()
    {
        if (_suspendPreview) return;

        _preview.BeginUpdate();
        _preview.Items.Clear();

        if (string.IsNullOrEmpty(_folder))
        {
            _preview.EndUpdate();
            _plan = null;
            _counts.Text = "no folder";
            _message.Text = "Choose a folder to get started.";
            _applyButton.Enabled = false;
            return;
        }

        try
        {
            _plan = RenameEngine.BuildPlan(_files, _rules);
        }
        catch (RuleException ex)
        {
            _preview.EndUpdate();
            _plan = null;
            _counts.Text = "rule error";
            _message.Text = ex.Message;
            _applyButton.Enabled = false;
            return;
        }

        int n = 0;
        foreach (var item in _plan.Items)
        {
            n++;
            var row = new ListViewItem(n.ToString());
            row.SubItems.Add(item.Original);
            row.SubItems.Add(item.Proposed);
            row.SubItems.Add(item.Status);
            row.SubItems.Add(item.Reason);
            row.ForeColor = item.Status switch
            {
                PlanStatus.Ok => Color.FromArgb(0, 100, 0),
                PlanStatus.Collision => Color.FromArgb(176, 0, 32),
                PlanStatus.Invalid => Color.FromArgb(120, 0, 0),
                _ => SystemColors.GrayText,
            };
            _preview.Items.Add(row);
        }
        _preview.EndUpdate();

        var s = _plan.Summary;
        _counts.Text = $"total {s.Total}  |  ok {s.Ok}  |  collision {s.Collision}  |  unchanged {s.Unchanged}  |  invalid {s.Invalid}";
        _message.Text = s.Ok > 0
            ? $"{s.Ok} file(s) will be renamed. Nothing has been changed yet."
            : "No file would change with the current rules.";
        _applyButton.Enabled = s.Ok > 0;
    }

    // ---- apply / undo ------------------------------------------------------

    private void ApplyRename()
    {
        if (_plan is null || _plan.Summary.Ok == 0) return;

        var s = _plan.Summary;
        string skipped = s.Total - s.Ok > 0
            ? $"\n\n{s.Total - s.Ok} file(s) will be skipped (collision {s.Collision}, unchanged {s.Unchanged}, invalid {s.Invalid})."
            : "";
        if (MessageBox.Show(this,
                $"Rename {s.Ok} file(s) in\n{_folder}?{skipped}",
                "Apply rename", MessageBoxButtons.OKCancel, MessageBoxIcon.Warning) != DialogResult.OK) return;

        try
        {
            var batch = Renamer.ApplyPlan(_folder, _plan.Items);
            string log = Renamer.SaveHistory(batch);
            _undo.Push(batch);
            _undoButton.Enabled = true;
            Rescan();
            _message.Text = $"Renamed {batch.Pairs.Count} file(s). Undo log: {log}";
        }
        catch (RenameFailedException ex)
        {
            Rescan();
            Warn(ex.Message);
        }
    }

    private void UndoLast()
    {
        if (_undo.Count == 0)
        {
            Warn("There is nothing to undo in this session. Use Tools > Undo from log file for an earlier batch.");
            return;
        }

        var batch = _undo.Pop();
        RunUndo(batch);
        _undoButton.Enabled = _undo.Count > 0;
    }

    private void UndoFromLog()
    {
        using var dialog = new OpenFileDialog
        {
            Title = "Pick an undo log",
            Filter = "Undo logs (*.json)|*.json|All files (*.*)|*.*",
            InitialDirectory = Directory.Exists(Renamer.HistoryFolder) ? Renamer.HistoryFolder : null,
        };
        if (dialog.ShowDialog(this) != DialogResult.OK) return;

        try
        {
            RunUndo(Renamer.LoadHistory(dialog.FileName));
        }
        catch (Exception ex)
        {
            Warn($"Cannot read that undo log:\n{ex.Message}");
        }
    }

    private void RunUndo(UndoBatch batch)
    {
        try
        {
            Renamer.Execute(batch.Folder, batch.Inverse());
            if (!string.Equals(batch.Folder, _folder, StringComparison.OrdinalIgnoreCase)) SetFolder(batch.Folder);
            else Rescan();
            _message.Text = $"Reverted {batch.Pairs.Count} file(s).";
        }
        catch (RenameFailedException ex)
        {
            Rescan();
            Warn(ex.Message);
        }
    }

    private void OpenHistoryFolder()
    {
        Directory.CreateDirectory(Renamer.HistoryFolder);
        System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo
        {
            FileName = Renamer.HistoryFolder,
            UseShellExecute = true,
        });
    }

    // ---- rules files -------------------------------------------------------

    private void LoadRules()
    {
        using var dialog = new OpenFileDialog
        {
            Title = "Load rules",
            Filter = "Rule sets (*.json)|*.json|All files (*.*)|*.*",
        };
        if (dialog.ShowDialog(this) != DialogResult.OK) return;

        try
        {
            var loaded = RulesJson.Load(dialog.FileName);
            _rules.ApplyTo = loaded.ApplyTo;
            _rules.Sort = loaded.Sort;
            _rules.Steps.Clear();
            _rules.Steps.AddRange(loaded.Steps);

            _suspendPreview = true;
            _applyToBox.SelectedIndex = loaded.ApplyTo == ApplyTo.NameAndExtension ? 1 : 0;
            _sortBox.SelectedIndex = (int)loaded.Sort;
            _suspendPreview = false;

            RefreshStepList(_rules.Steps.Count > 0 ? 0 : -1);
            _message.Text = $"Loaded {_rules.Steps.Count} step(s) from {dialog.FileName}";
        }
        catch (Exception ex)
        {
            Warn($"Cannot load that rule set:\n{ex.Message}");
        }
    }

    private void SaveRules()
    {
        using var dialog = new SaveFileDialog
        {
            Title = "Save rules",
            Filter = "Rule sets (*.json)|*.json",
            FileName = "rules.json",
        };
        if (dialog.ShowDialog(this) != DialogResult.OK) return;

        try
        {
            RulesJson.Save(dialog.FileName, _rules);
            _message.Text = $"Saved rules to {dialog.FileName}";
        }
        catch (Exception ex)
        {
            Warn($"Cannot save the rule set:\n{ex.Message}");
        }
    }

    private void ExportPlan()
    {
        if (_plan is null)
        {
            Warn("There is no plan to export yet.");
            return;
        }

        using var dialog = new SaveFileDialog
        {
            Title = "Export plan",
            Filter = "Plans (*.json)|*.json",
            FileName = "plan.json",
        };
        if (dialog.ShowDialog(this) != DialogResult.OK) return;

        try
        {
            PlanJson.Save(dialog.FileName, _plan);
            _message.Text = $"Exported plan to {dialog.FileName}";
        }
        catch (Exception ex)
        {
            Warn($"Cannot export the plan:\n{ex.Message}");
        }
    }

    private void ShowAbout() => MessageBox.Show(this,
        "Batch Rename Studio\n\n" +
        "Preview-first batch renaming for Windows.\n" +
        "The GUI preview and the headless planner share one engine.\n\n" +
        "Headless:\n" +
        "  BatchRenameStudio.exe --plan --dir <folder> --rules <rules.json> --out <plan.json>",
        "About", MessageBoxButtons.OK, MessageBoxIcon.Information);

    private void Warn(string message) =>
        MessageBox.Show(this, message, "Batch Rename Studio", MessageBoxButtons.OK, MessageBoxIcon.Warning);
}

