namespace BatchRenameStudio.Core;

/// <summary>What part of a file name the steps operate on.</summary>
public enum ApplyTo
{
    Name,
    NameAndExtension,
}

/// <summary>Processing order of the files in the folder.</summary>
public enum SortMode
{
    Name,
    Created,
    Modified,
}

public enum StepOp
{
    Replace,
    Insert,
    Remove,
    Sequence,
    Case,
    Extension,
}

public enum InsertPosition
{
    Prefix,
    Suffix,
    Index,
}

public enum SequencePosition
{
    Prefix,
    Suffix,
}

public enum CaseMode
{
    Upper,
    Lower,
    Title,
}

public enum ExtensionMode
{
    Lower,
    Upper,
    Set,
}

/// <summary>
/// One rule step. A single mutable class carries the union of every op's fields; only the
/// fields belonging to <see cref="Op"/> are read. This keeps the JSON contract, the engine and
/// the GUI editor working on exactly one shape (see docs/DECISIONS.md, D-04).
/// </summary>
public sealed class RuleStep
{
    public StepOp Op { get; set; } = StepOp.Replace;

    /// <summary>GUI-only convenience: a disabled step is dropped when the rule set is saved/planned.</summary>
    public bool Enabled { get; set; } = true;

    // replace
    public string Find { get; set; } = "";
    public string ReplaceWith { get; set; } = "";
    public bool Regex { get; set; }
    public bool IgnoreCase { get; set; }

    // insert
    public string Text { get; set; } = "";
    public InsertPosition Position { get; set; } = InsertPosition.Prefix;
    public int Index { get; set; }

    // remove
    public int From { get; set; }
    public int Count { get; set; }

    // sequence
    public string Pattern { get; set; } = "{n:000}_";
    public long Start { get; set; } = 1;
    public long Step { get; set; } = 1;
    public SequencePosition SeqPosition { get; set; } = SequencePosition.Prefix;

    // case
    public CaseMode CaseMode { get; set; } = CaseMode.Lower;

    // extension
    public ExtensionMode ExtensionMode { get; set; } = ExtensionMode.Lower;
    public string Value { get; set; } = "";

    public RuleStep Clone() => (RuleStep)MemberwiseClone();
}

public sealed class RuleSet
{
    public ApplyTo ApplyTo { get; set; } = ApplyTo.Name;
    public SortMode Sort { get; set; } = SortMode.Name;
    public List<RuleStep> Steps { get; } = new();

    public RuleSet Clone()
    {
        var copy = new RuleSet { ApplyTo = ApplyTo, Sort = Sort };
        foreach (var s in Steps) copy.Steps.Add(s.Clone());
        return copy;
    }
}

/// <summary>A file considered by the engine. Kept free of IO so the engine stays unit-testable.</summary>
public sealed record FileEntry(string Name, DateTime CreatedUtc, DateTime ModifiedUtc);

public static class PlanStatus
{
    public const string Ok = "ok";
    public const string Collision = "collision";
    public const string Unchanged = "unchanged";
    public const string Invalid = "invalid";
}

public sealed record PlanItem(string Original, string Proposed, string Status, string Reason);

public sealed class PlanSummary
{
    public int Total { get; set; }
    public int Ok { get; set; }
    public int Collision { get; set; }
    public int Unchanged { get; set; }
    public int Invalid { get; set; }
}

public sealed class RenamePlan
{
    public const int CurrentSchemaVersion = 1;

    public int SchemaVersion { get; init; } = CurrentSchemaVersion;
    public List<PlanItem> Items { get; init; } = new();
    public PlanSummary Summary { get; init; } = new();
}

