/// <summary>A file considered by the engine. Kept free of IO so the engine stays unit-testable.</summary>
public sealed record FileEntry(string Name, DateTime CreatedUtc, DateTime ModifiedUtc);

public static class PlanStatus
{
    public const string Ok = "ok";
    public const string Collision = "collision";
    public const string Unchanged = "unchanged";
    public const string Invalid = "invalid";
}

public sealed record PlanItem(string Original, string Proposed, string Status, string Reason);

public sealed class PlanSummary
{
    public int Total { get; set; }
    public int Ok { get; set; }
    public int Collision { get; set; }
    public int Unchanged { get; set; }
    public int Invalid { get; set; }
}

public sealed class RenamePlan
{
    public const int CurrentSchemaVersion = 1;

    public int SchemaVersion { get; init; } = CurrentSchemaVersion;
    public List<PlanItem> Items { get; init; } = new();
    public PlanSummary Summary { get; init; } = new();
}

using System.Text.RegularExpressions;

namespace BatchRenameStudio.Core;

/// <summary>Thrown when a rule set cannot be turned into a runnable plan (e.g. a bad regex).</summary>
public sealed class RuleException : Exception
{
    public RuleException(string message) : base(message) { }
}

/// <summary>
/// Turns a folder listing plus a rule set into a <see cref="RenamePlan"/>.
/// This type is the single source of truth for the rename semantics: the headless
/// <c>--plan</c> mode and the GUI preview both call <see cref="BuildPlan"/>.
/// </summary>
public static class RenameEngine
{
    private static readonly Regex CounterToken = new(@"\{n:(0+)\}", RegexOptions.CultureInvariant);

    public static RenamePlan BuildPlan(IReadOnlyList<FileEntry> files, RuleSet rules)
    {
        var steps = Prepare(rules);
        var ordered = Sort(files, rules.Sort);

        var proposals = new string[ordered.Count];
        for (int i = 0; i < ordered.Count; i++)
        {
            proposals[i] = Apply(ordered[i].Name, rules.ApplyTo, steps, i);
        }

        return Classify(ordered, proposals);
    }

    /// <summary>Contract rule 5 + rule 15: deterministic processing order.</summary>
    public static List<FileEntry> Sort(IReadOnlyList<FileEntry> files, SortMode mode) => mode switch
    {
        // Ordinal (codepoint) ascending, case sensitive.
        SortMode.Name => files.OrderBy(f => f.Name, StringComparer.Ordinal).ToList(),
        // Timestamp ascending; the ordinal name is a tie-break so equal timestamps stay deterministic.
        SortMode.Created => files.OrderBy(f => f.CreatedUtc).ThenBy(f => f.Name, StringComparer.Ordinal).ToList(),
        SortMode.Modified => files.OrderBy(f => f.ModifiedUtc).ThenBy(f => f.Name, StringComparer.Ordinal).ToList(),
        _ => files.OrderBy(f => f.Name, StringComparer.Ordinal).ToList(),
    };

    /// <summary>
    /// Runs every step over one file name. <paramref name="ordinal"/> is the 0-based position in
    /// processing order and drives the sequence counter (which advances for every file).
    /// </summary>
    public static string Apply(string originalName, ApplyTo applyTo, IReadOnlyList<PreparedStep> steps, int ordinal)
    {
        if (applyTo == ApplyTo.NameAndExtension)
        {
            string whole = originalName;
            foreach (var step in steps)
            {
                whole = step.Def.Op == StepOp.Extension
                    // Rule 11 + 12: an extension step always works on the trailing extension,
                    // even when the target string is the whole name.
                    ? ApplyExtensionToWholeName(whole, step)
                    : ApplyToTarget(whole, step, ordinal);
            }
            return whole;
        }

        var (baseName, ext) = NameRules.Split(originalName);
        foreach (var step in steps)
        {
            if (step.Def.Op == StepOp.Extension) ext = ApplyExtension(ext, step);
            else baseName = ApplyToTarget(baseName, step, ordinal);
        }
        return NameRules.Join(baseName, ext);
    }

    private static string ApplyExtensionToWholeName(string whole, PreparedStep step)
    {
        var (b, e) = NameRules.Split(whole);
        return NameRules.Join(b, ApplyExtension(e, step));
    }

    private static string ApplyExtension(string ext, PreparedStep step) => step.Def.ExtensionMode switch
    {
        ExtensionMode.Lower => NameRules.ToLower(ext),
        ExtensionMode.Upper => NameRules.ToUpper(ext),
        ExtensionMode.Set => step.Def.Value,
        _ => ext,
    };

    private static string ApplyToTarget(string target, PreparedStep step, int ordinal)
    {
        var d = step.Def;
        switch (d.Op)
        {
            case StepOp.Replace:
                if (d.Find.Length == 0) return target;           // nothing to look for: no-op
                return step.Rx is not null
                    ? step.Rx.Replace(target, d.ReplaceWith)
                    : target.Replace(d.Find, d.ReplaceWith,
                        d.IgnoreCase ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal);

            case StepOp.Insert:
                switch (d.Position)
                {
                    case InsertPosition.Prefix: return d.Text + target;
                    case InsertPosition.Suffix: return target + d.Text;
                    default:
                        int at = Math.Clamp(d.Index, 0, target.Length);
                        return target.Insert(at, d.Text);
                }

            case StepOp.Remove:
            {
                int from = Math.Clamp(d.From, 0, target.Length);
                int count = Math.Clamp(d.Count, 0, target.Length - from);
                return count == 0 ? target : target.Remove(from, count);
            }

            case StepOp.Sequence:
            {
                long value = d.Start + (long)ordinal * d.Step;
                string rendered = RenderSequence(d.Pattern, value);
                return d.SeqPosition == SequencePosition.Suffix ? target + rendered : rendered + target;
            }

            case StepOp.Case:
                return d.CaseMode switch
                {
                    CaseMode.Upper => NameRules.ToUpper(target),
                    CaseMode.Lower => NameRules.ToLower(target),
                    _ => NameRules.ToTitle(target),
                };

            default:
                return target;
        }
    }

    /// <summary>Expands the <c>{n:000}</c> token(s) of a sequence pattern; other text is literal.</summary>
    public static string RenderSequence(string pattern, long value) =>
        CounterToken.Replace(pattern, m => NameRules.FormatCounter(value, m.Groups[1].Value.Length));

    /// <summary>Contract rule 13: status precedence invalid &gt; collision &gt; unchanged &gt; ok.</summary>
    private static RenamePlan Classify(IReadOnlyList<FileEntry> ordered, IReadOnlyList<string> proposals)
    {
        var existing = new HashSet<string>(ordered.Select(f => f.Name), StringComparer.OrdinalIgnoreCase);

        var proposedCounts = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        foreach (var p in proposals)
        {
            proposedCounts.TryGetValue(p, out int n);
            proposedCounts[p] = n + 1;
        }

        var plan = new RenamePlan();
        for (int i = 0; i < ordered.Count; i++)
        {
            string original = ordered[i].Name;
            string proposed = proposals[i];

            string status;
            string reason;

            string? invalid = NameRules.GetInvalidReason(proposed);
            if (invalid is not null)
            {
                status = PlanStatus.Invalid;
                reason = invalid;
            }
            else if (proposedCounts[proposed] > 1)
            {
                status = PlanStatus.Collision;
                reason = "another item proposes the same name";
            }
            else if (existing.Contains(proposed) && !string.Equals(proposed, original, StringComparison.OrdinalIgnoreCase))
            {
                status = PlanStatus.Collision;
                reason = "a different existing file already uses this name";
            }
            else if (string.Equals(proposed, original, StringComparison.Ordinal))
            {
                status = PlanStatus.Unchanged;
                reason = "";
            }
            else
            {
                status = PlanStatus.Ok;
                reason = "";
            }

            plan.Items.Add(new PlanItem(original, proposed, status, reason));
        }

        plan.Summary.Total = plan.Items.Count;
        plan.Summary.Ok = plan.Items.Count(i => i.Status == PlanStatus.Ok);
        plan.Summary.Collision = plan.Items.Count(i => i.Status == PlanStatus.Collision);
        plan.Summary.Unchanged = plan.Items.Count(i => i.Status == PlanStatus.Unchanged);
        plan.Summary.Invalid = plan.Items.Count(i => i.Status == PlanStatus.Invalid);
        return plan;
    }

    /// <summary>A step with its per-run state (a compiled regex) resolved once instead of per file.</summary>
    public sealed class PreparedStep
    {
        public PreparedStep(RuleStep def, Regex? rx)
        {
            Def = def;
            Rx = rx;
        }

        public RuleStep Def { get; }
        public Regex? Rx { get; }
    }

    public static List<PreparedStep> Prepare(RuleSet rules)
    {
        var list = new List<PreparedStep>(rules.Steps.Count);
        for (int i = 0; i < rules.Steps.Count; i++)
        {
            var s = rules.Steps[i];
            if (!s.Enabled) continue;

            Regex? rx = null;
            if (s.Op == StepOp.Replace && s.Regex && s.Find.Length > 0)
            {
                var options = RegexOptions.CultureInvariant;
                if (s.IgnoreCase) options |= RegexOptions.IgnoreCase;
                try
                {
                    rx = new Regex(s.Find, options);
                }
                catch (ArgumentException ex)
                {
                    throw new RuleException($"step {i + 1} (replace): invalid regex \"{s.Find}\": {ex.Message}");
                }
            }
            list.Add(new PreparedStep(s, rx));
        }
        return list;
    }
}

using BatchRenameStudio.Core;

namespace BatchRenameStudio.Ui;

/// <summary>Presentation helpers shared by the step list and the step editor.</summary>
internal static class StepUi
{
    public static string OpTitle(StepOp op) => op switch
    {
        StepOp.Replace => "Replace text",
        StepOp.Insert => "Insert text",
        StepOp.Remove => "Remove characters",
        StepOp.Sequence => "Numbering",
        StepOp.Case => "Change case",
        StepOp.Extension => "Extension",
        _ => op.ToString(),
    };

    /// <summary>One-line human summary of a step, shown in the rule list.</summary>
    public static string Describe(RuleStep s) => s.Op switch
    {
        StepOp.Replace =>
            $"Replace {(s.Regex ? "regex " : "")}\"{s.Find}\" -> \"{s.ReplaceWith}\"{(s.IgnoreCase ? " (ignore case)" : "")}",
        StepOp.Insert => s.Position switch
        {
            InsertPosition.Prefix => $"Insert \"{s.Text}\" at the start",
            InsertPosition.Suffix => $"Insert \"{s.Text}\" at the end",
            _ => $"Insert \"{s.Text}\" at index {s.Index}",
        },
        StepOp.Remove => $"Remove {s.Count} char(s) from index {s.From}",
        StepOp.Sequence =>
            $"Number \"{s.Pattern}\" as {(s.SeqPosition == SequencePosition.Suffix ? "suffix" : "prefix")}, start {s.Start} step {s.Step}",
        StepOp.Case => $"Case -> {s.CaseMode.ToString().ToLowerInvariant()}",
        StepOp.Extension => s.ExtensionMode == ExtensionMode.Set
            ? $"Extension -> set \"{s.Value}\""
            : $"Extension -> {s.ExtensionMode.ToString().ToLowerInvariant()}",
        _ => s.Op.ToString(),
    };

    /// <summary>Wrapper so a <see cref="CheckedListBox"/> can show a step and keep a reference to it.</summary>
    public sealed class StepBox
    {
        public StepBox(RuleStep step) => Step = step;

        public RuleStep Step { get; }

        public override string ToString() => Describe(Step);
    }
}

using BatchRenameStudio.Core;

namespace BatchRenameStudio.Ui;

/// <summary>
/// Modal editor for one rule step. The op is fixed when the step is created; the dialog only
/// shows the fields that op actually uses, so the form never presents meaningless inputs.
/// </summary>
internal sealed class StepEditorForm : Form
{
    private readonly RuleStep _step;
    private readonly TableLayoutPanel _grid;
    private readonly Label _hint;

    private TextBox? _find, _replaceWith, _text, _pattern, _value;
    private CheckBox? _regex, _ignoreCase;
    private ComboBox? _position, _mode;
    private NumericUpDown? _index, _from, _count, _start, _stepBy;

    public RuleStep Result => _step;

    public StepEditorForm(RuleStep step)
    {
        _step = step.Clone();

        Text = StepUi.OpTitle(_step.Op);
        FormBorderStyle = FormBorderStyle.FixedDialog;
        MinimizeBox = false;
        MaximizeBox = false;
        StartPosition = FormStartPosition.CenterParent;
        ClientSize = new Size(460, 240);
        Padding = new Padding(12);

        _grid = new TableLayoutPanel
        {
            Dock = DockStyle.Fill,
            ColumnCount = 2,
            AutoSize = true,
            GrowStyle = TableLayoutPanelGrowStyle.AddRows,
        };
        _grid.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute, 120));
        _grid.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 100));

        _hint = new Label
        {
            Dock = DockStyle.Top,
            AutoSize = false,
            Height = 34,
            ForeColor = SystemColors.GrayText,
            Text = HintFor(_step.Op),
        };

        var buttons = new FlowLayoutPanel
        {
            Dock = DockStyle.Bottom,
            FlowDirection = FlowDirection.RightToLeft,
            Height = 40,
            Padding = new Padding(0, 6, 0, 0),
        };
        var cancel = new Button { Text = "Cancel", DialogResult = DialogResult.Cancel, Width = 90 };
        var ok = new Button { Text = "OK", DialogResult = DialogResult.OK, Width = 90 };
        ok.Click += (_, _) => Commit();
        buttons.Controls.Add(cancel);
        buttons.Controls.Add(ok);

        Controls.Add(_grid);
        Controls.Add(_hint);
        Controls.Add(buttons);
        AcceptButton = ok;
        CancelButton = cancel;

        BuildFields();
    }

    private static string HintFor(StepOp op) => op switch
    {
        StepOp.Replace => "Replaces every occurrence. In regex mode $1 refers to a capture group.",
        StepOp.Insert => "Index is 0-based and clamped to the length of the target text.",
        StepOp.Remove => "From is 0-based; count is clamped to what is left.",
        StepOp.Sequence => "Pattern holds literal text plus one {n:000} token; the zeros set the width.",
        StepOp.Case => "Title case uppercases the first letter of each run of letters.",
        StepOp.Extension => "Always applies to the extension, whatever the target setting is. No leading dot.",
        _ => "",
    };

    private void BuildFields()
    {
        switch (_step.Op)
        {
            case StepOp.Replace:
                _find = AddText("Find", _step.Find);
                _replaceWith = AddText("Replace with", _step.ReplaceWith);
                _regex = AddCheck("Regular expression", _step.Regex);
                _ignoreCase = AddCheck("Ignore case", _step.IgnoreCase);
                break;

            case StepOp.Insert:
                _text = AddText("Text", _step.Text);
                _position = AddCombo("Position", new[] { "prefix", "suffix", "index" }, _step.Position switch
                {
                    InsertPosition.Suffix => 1,
                    InsertPosition.Index => 2,
                    _ => 0,
                });
                _index = AddNumber("Index", _step.Index, 0, 4096);
                _position.SelectedIndexChanged += (_, _) => _index!.Enabled = _position!.SelectedIndex == 2;
                _index.Enabled = _position.SelectedIndex == 2;
                break;

            case StepOp.Remove:
                _from = AddNumber("From", _step.From, 0, 4096);
                _count = AddNumber("Count", _step.Count, 0, 4096);
                break;

            case StepOp.Sequence:
                _pattern = AddText("Pattern", _step.Pattern);
                _start = AddNumber("Start", _step.Start, -1_000_000, 1_000_000);
                _stepBy = AddNumber("Step", _step.Step, -1_000_000, 1_000_000);
                _position = AddCombo("Position", new[] { "prefix", "suffix" },
                    _step.SeqPosition == SequencePosition.Suffix ? 1 : 0);
                break;

            case StepOp.Case:
                _mode = AddCombo("Mode", new[] { "upper", "lower", "title" }, _step.CaseMode switch
                {
                    CaseMode.Upper => 0,
                    CaseMode.Lower => 1,
                    _ => 2,
                });
                break;

            case StepOp.Extension:
                _mode = AddCombo("Mode", new[] { "lower", "upper", "set" }, _step.ExtensionMode switch
                {
                    ExtensionMode.Lower => 0,
                    ExtensionMode.Upper => 1,
                    _ => 2,
                });
                _value = AddText("Value", _step.Value);
                _mode.SelectedIndexChanged += (_, _) => _value!.Enabled = _mode!.SelectedIndex == 2;
                _value.Enabled = _mode.SelectedIndex == 2;
                break;
        }
    }

    private void Commit()
    {
        switch (_step.Op)
        {
            case StepOp.Replace:
                _step.Find = _find!.Text;
                _step.ReplaceWith = _replaceWith!.Text;
                _step.Regex = _regex!.Checked;
                _step.IgnoreCase = _ignoreCase!.Checked;
                break;

            case StepOp.Insert:
                _step.Text = _text!.Text;
                _step.Position = _position!.SelectedIndex switch
                {
                    1 => InsertPosition.Suffix,
                    2 => InsertPosition.Index,
                    _ => InsertPosition.Prefix,
                };
                _step.Index = (int)_index!.Value;
                break;

            case StepOp.Remove:
                _step.From = (int)_from!.Value;
                _step.Count = (int)_count!.Value;
                break;

            case StepOp.Sequence:
                _step.Pattern = _pattern!.Text;
                _step.Start = (long)_start!.Value;
                _step.Step = (long)_stepBy!.Value;
                _step.SeqPosition = _position!.SelectedIndex == 1 ? SequencePosition.Suffix : SequencePosition.Prefix;
                break;

            case StepOp.Case:
                _step.CaseMode = _mode!.SelectedIndex switch
                {
                    0 => CaseMode.Upper,
                    1 => CaseMode.Lower,
                    _ => CaseMode.Title,
                };
                break;

            case StepOp.Extension:
                _step.ExtensionMode = _mode!.SelectedIndex switch
                {
                    0 => ExtensionMode.Lower,
                    1 => ExtensionMode.Upper,
                    _ => ExtensionMode.Set,
                };
                _step.Value = _value!.Text;
                break;
        }
    }

    // ---- row builders ------------------------------------------------------

    private void AddRow(string label, Control control)
    {
        _grid.Controls.Add(new Label
        {
            Text = label,
            Dock = DockStyle.Fill,
            TextAlign = ContentAlignment.MiddleLeft,
            Margin = new Padding(0, 6, 6, 0),
        });
        control.Dock = DockStyle.Fill;
        control.Margin = new Padding(0, 4, 0, 4);
        _grid.Controls.Add(control);
    }

    private TextBox AddText(string label, string value)
    {
        var box = new TextBox { Text = value };
        AddRow(label, box);
        return box;
    }

    private CheckBox AddCheck(string label, bool value)
    {
        var box = new CheckBox { Checked = value, Text = "" };
        AddRow(label, box);
        return box;
    }

    private ComboBox AddCombo(string label, string[] items, int selected)
    {
        var box = new ComboBox { DropDownStyle = ComboBoxStyle.DropDownList };
        box.Items.AddRange(items);
        box.SelectedIndex = Math.Clamp(selected, 0, items.Length - 1);
        AddRow(label, box);
        return box;
    }

    private NumericUpDown AddNumber(string label, long value, long min, long max)
    {
        var box = new NumericUpDown
        {
            Minimum = min,
            Maximum = max,
            Value = Math.Clamp(value, min, max),
        };
        AddRow(label, box);
        return box;
    }
}

