using System.Globalization;
using BatchRenameStudio.Core;

namespace BatchRenameStudio.Cli;

/// <summary>
/// Optional extension of the CLI (NOT part of the fixed --plan contract):
/// <c>BatchRenameStudio.exe --apply --dir &lt;folder&gt; --rules &lt;rules.json&gt; [--out &lt;plan.json&gt;]</c>
/// builds the very same plan, then renames the items whose status is "ok" and writes an undo log.
/// </summary>
internal static class ApplyCommand
{
    public const string Usage =
        "usage: BatchRenameStudio.exe --apply --dir <folder> --rules <rules.json> [--out <plan.json>]";

    public static bool IsRequested(string[] args) =>
        args.Any(a => string.Equals(a, "--apply", StringComparison.OrdinalIgnoreCase));

    public static int Run(string[] args)
    {
        string? dir = null, rulesPath = null, outPath = null;

        for (int i = 0; i < args.Length; i++)
        {
            string arg = args[i];
            if (string.Equals(arg, "--apply", StringComparison.OrdinalIgnoreCase)) continue;

            string name = arg, inline = "";
            int eq = arg.IndexOf('=');
            bool hasInline = arg.StartsWith("--", StringComparison.Ordinal) && eq > 0;
            if (hasInline)
            {
                name = arg[..eq];
                inline = arg[(eq + 1)..];
            }

            switch (name.ToLowerInvariant())
            {
                case "--dir":
                    if (!CliArgs.TryValue(args, ref i, hasInline, inline, out dir)) return Fail("--dir needs a value");
                    break;
                case "--rules":
                    if (!CliArgs.TryValue(args, ref i, hasInline, inline, out rulesPath)) return Fail("--rules needs a value");
                    break;
                case "--out":
                    if (!CliArgs.TryValue(args, ref i, hasInline, inline, out outPath)) return Fail("--out needs a value");
                    break;
                default:
                    return Fail($"unknown argument \"{arg}\"");
            }
        }

        if (string.IsNullOrWhiteSpace(dir)) return Fail("--dir is required");
        if (string.IsNullOrWhiteSpace(rulesPath)) return Fail("--rules is required");

        RuleSet rules;
        List<FileEntry> files;
        RenamePlan plan;
        try
        {
            rules = RulesJson.Load(rulesPath!);
            files = FolderScanner.Scan(dir!);
            plan = RenameEngine.BuildPlan(files, rules);
        }
        catch (RulesFormatException ex) { return Error(ExitCodes.BadRules, ex.Message); }
        catch (RuleException ex) { return Error(ExitCodes.BadRules, ex.Message); }
        catch (DirectoryNotFoundException) { return Error(ExitCodes.Io, $"folder not found: {dir}"); }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            return Error(ExitCodes.Io, ex.Message);
        }

        if (!string.IsNullOrWhiteSpace(outPath))
        {
            try
            {
                PlanJson.Save(outPath!, plan);
            }
            catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
            {
                return Error(ExitCodes.Io, $"cannot write plan \"{outPath}\": {ex.Message}");
            }
        }

        UndoBatch batch;
        try
        {
            batch = Renamer.ApplyPlan(dir!, plan.Items);
        }
        catch (RenameFailedException ex)
        {
            return Error(ExitCodes.Io, ex.Message);
        }

        string log;
        try
        {
            log = Renamer.SaveHistory(batch);
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            log = $"(not written: {ex.Message})";
        }

        var s = plan.Summary;
        Console.Out.WriteLine(string.Create(CultureInfo.InvariantCulture,
            $"applied: renamed={batch.Pairs.Count} skipped={s.Total - s.Ok} (collision={s.Collision} unchanged={s.Unchanged} invalid={s.Invalid}) undo={log}"));
        return ExitCodes.Success;
    }

    private static int Fail(string message)
    {
        Console.Error.WriteLine($"error: {message}");
        Console.Error.WriteLine(Usage);
        return ExitCodes.Usage;
    }

    private static int Error(int code, string message)
    {
        Console.Error.WriteLine($"error: {message}");
        return code;
    }
}

/// <summary>Shared bits of the tiny hand-rolled argument parser.</summary>
internal static class CliArgs
{
    /// <summary>Reads either <c>--name value</c> or <c>--name=value</c>.</summary>
    public static bool TryValue(string[] args, ref int i, bool hasInline, string inline, out string? value)
    {
        if (hasInline)
        {
            value = inline;
            return value.Length > 0;
        }
        if (i + 1 >= args.Length)
        {
            value = null;
            return false;
        }
        value = args[++i];
        return true;
    }
}

