using BatchRenameStudio.Cli;
using BatchRenameStudio.Ui;

namespace BatchRenameStudio;

internal static class Program
{
    /// <summary>
    /// Two entry points in one binary: with <c>--plan</c> the process behaves as a headless
    /// planner and never shows a window; otherwise the GUI starts (optionally on a folder
    /// passed as the first argument).
    /// </summary>
    [STAThread]
    private static int Main(string[] args)
    {
        if (PlanCommand.IsRequested(args) || PlanCommand.IsHelpRequested(args))
        {
            ConsoleBridge.Attach();
            try
            {
                if (PlanCommand.IsHelpRequested(args) && !PlanCommand.IsRequested(args))
                {
                    Console.Out.WriteLine(PlanCommand.Usage);
                    return ExitCodes.Success;
                }
                return PlanCommand.Run(args);
            }
            catch (Exception ex)
            {
                Console.Error.WriteLine($"error: {ex.Message}");
                return ExitCodes.Io;
            }
            finally
            {
                ConsoleBridge.Detach();
            }
        }

        ApplicationConfiguration.Initialize();
        string? folder = args.FirstOrDefault(a => !a.StartsWith('-') && Directory.Exists(a));
        Application.Run(new MainForm(folder));
        return ExitCodes.Success;
    }
}

