using System.Globalization;
using BatchRenameStudio.Core;

namespace BatchRenameStudio.Cli;

/// <summary>
/// Optional extension of the CLI (NOT part of the fixed --plan contract):
/// <c>BatchRenameStudio.exe --undo &lt;undo-log.json&gt;</c> reverts a batch written by
/// <c>--apply</c> or by the GUI.
/// </summary>
internal static class UndoCommand
{
    public const string Usage = "usage: BatchRenameStudio.exe --undo <undo-log.json>";

    public static bool IsRequested(string[] args) =>
        args.Any(a => a.StartsWith("--undo", StringComparison.OrdinalIgnoreCase));

    public static int Run(string[] args)
    {
        string? logPath = null;
        for (int i = 0; i < args.Length; i++)
        {
            string arg = args[i];
            int eq = arg.IndexOf('=');
            bool hasInline = arg.StartsWith("--", StringComparison.Ordinal) && eq > 0;
            string name = hasInline ? arg[..eq] : arg;
            string inline = hasInline ? arg[(eq + 1)..] : "";

            if (!string.Equals(name, "--undo", StringComparison.OrdinalIgnoreCase))
            {
                Console.Error.WriteLine($"error: unknown argument \"{arg}\"");
                Console.Error.WriteLine(Usage);
                return ExitCodes.Usage;
            }
            if (!CliArgs.TryValue(args, ref i, hasInline, inline, out logPath))
            {
                Console.Error.WriteLine("error: --undo needs the path of an undo log");
                Console.Error.WriteLine(Usage);
                return ExitCodes.Usage;
            }
        }

        if (string.IsNullOrWhiteSpace(logPath))
        {
            Console.Error.WriteLine("error: --undo needs the path of an undo log");
            return ExitCodes.Usage;
        }

        UndoBatch batch;
        try
        {
            batch = Renamer.LoadHistory(logPath!);
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"error: cannot read undo log \"{logPath}\": {ex.Message}");
            return ExitCodes.BadRules;
        }

        try
        {
            Renamer.Execute(batch.Folder, batch.Inverse());
        }
        catch (RenameFailedException ex)
        {
            Console.Error.WriteLine($"error: {ex.Message}");
            return ExitCodes.Io;
        }

        Console.Out.WriteLine(string.Create(CultureInfo.InvariantCulture,
            $"undone: reverted={batch.Pairs.Count} folder={batch.Folder}"));
        return ExitCodes.Success;
    }
}

