        {
            batch = Renamer.LoadHistory(logPath!);
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"error: cannot read undo log \"{logPath}\": {ex.Message}");
            return ExitCodes.BadRules;
        }

        try
        {
            Renamer.Execute(batch.Folder, batch.Inverse());
        }
        catch (RenameFailedException ex)
        {
            Console.Error.WriteLine($"error: {ex.Message}");
            return ExitCodes.Io;
        }

        Console.Out.WriteLine(string.Create(CultureInfo.InvariantCulture,
            $"undone: reverted={batch.Pairs.Count} folder={batch.Folder}"));
        return ExitCodes.Success;
    }
}

