    /// <summary>
    /// A GUI crash must never be a silent disappearing window: write a log next to the undo
    /// history and tell the user where it is.
    /// </summary>
    private static void ReportFatal(Exception? ex)
    {
        if (ex is null) return;

        string path;
        try
        {
            string dir = Path.Combine(
                Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
                "BatchRenameStudio");
            Directory.CreateDirectory(dir);
            path = Path.Combine(dir, $"crash-{DateTime.UtcNow:yyyyMMdd-HHmmss-fff}.log");
            File.WriteAllText(path, ex.ToString());
        }
        catch (Exception writeFailure)
        {
            path = $"(could not be written: {writeFailure.Message})";
        }

        MessageBox.Show(
            $"Batch Rename Studio hit an unexpected error and may not be usable.\n\n{ex.Message}\n\nDetails: {path}",
            "Batch Rename Studio", MessageBoxButtons.OK, MessageBoxIcon.Error);
    }
}

